#!/usr/bin/env bash
# Regenerates docs/specs/README.md from the header of each docs/specs/NNN-*/NNN-spec.md: the title (the `# NNN — ` line),
# and the `Status:`, `Release:` and `Sources:` lines in the first ten lines. One table per Status group (built, in
# progress, to be built, rejected or superseded), rows sorted by number, with links to the spec and to the plan, tasks
# and api files beside it. Deterministic: sorted, LF, no dates.
#   gen-spec-index.sh            print the regenerated file
#   gen-spec-index.sh --write    rewrite docs/specs/README.md
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
. "$root/scripts/release/version.sh"
die() { echo "gen-spec-index: $*" >&2; exit 1; }
v="$(bayan_version "$root")"
out="$root/docs/specs/README.md"
t="$(mktemp -d)"; trap 'rm -rf "$t"' EXIT
export LC_ALL=C

# Cell text: `|` escaped.
esc() { sed 's/|/\\|/g' <<< "$1"; }

for dir in "$root"/docs/specs/[0-9][0-9][0-9]-*/; do
  [ -d "$dir" ] || continue
  slug="$(basename "$dir")"; n="${slug%%-*}"
  spec="$dir$n-spec.md"; rel="docs/specs/$slug/$n-spec.md"
  [ -f "$spec" ] || die "$rel not found"
  top="$(head -n 10 "$spec")"
  for key in Status Release Sources; do
    grep -q "^$key: " <<< "$top" || die "$rel: no $key: line in the first ten lines"
  done
  status="$(grep -m 1 '^Status: ' <<< "$top" | sed 's/^Status: //')"
  release="$(grep -m 1 '^Release: ' <<< "$top" | sed 's/^Release: //')"
  sources="$(grep -m 1 '^Sources: ' <<< "$top" | sed 's/^Sources: //')"
  title="$(grep -m 1 '^# ' "$spec" | sed -E "s/^# $n — //")"
  case "$status" in
    done*) sec=1 ;;
    "in progress"*) sec=2 ;;
    approved*|open*|deferred*|draft*) sec=3 ;;
    rejected*|superseded*) sec=4 ;;
    *) die "$rel: unknown Status '$status'" ;;
  esac
  files=""
  for k in plan tasks api; do
    [ -f "$dir$n-$k.md" ] || continue
    files="${files:+$files, }[$k]($slug/$n-$k.md)"
  done
  printf '%s|| [%s](%s/%s-spec.md) | %s | %s | %s | %s | %s |\n' "$sec" "$n" "$slug" "$n" "$(esc "$title")" "$(esc "$status")" \
    "$(esc "$release")" "$(esc "$sources")" "$files" >> "$t/rows"
done
[ -s "$t/rows" ] || die "no docs/specs/NNN-*/NNN-spec.md"

gen() {
  printf '# Feature specs\n\nVersion: %s (matches `bayan --version`)\n\n' "$v"
  printf 'This file is generated by `bash scripts/docs/gen-spec-index.sh --write` from the header of each spec. Do not edit it by hand.\n'
  local i name
  for i in 1 2 3 4; do
    case "$i" in 1) name="Built" ;; 2) name="In progress" ;; 3) name="To be built" ;; 4) name="Rejected or superseded" ;; esac
    grep -q "^$i|" "$t/rows" || continue
    printf '\n## %s\n\n| Spec | Title | Status | Release | Sources | Files |\n|---|---|---|---|---|---|\n' "$name"
    grep "^$i|" "$t/rows" | sed "s/^$i|//"
    [ "$i" != 4 ] || printf '\nFeatures rejected without a spec are in [bayan-not-planned.md](../bayan-not-planned.md).\n'
  done
}

if [ "${1:-}" = --write ]; then gen > "$t/out"; cat "$t/out" > "$out"; else gen; fi
